func cgo_wxGetPasswordFromUser(message string, caption string, defaultText string, parent unsafe.Pointer, buffer string) int {
	cMessage := C.CString(message)
	cCaption := C.CString(caption)
	cDefaultText := C.CString(defaultText)
	cBuffer := C.CString(buffer)
	defer C.free(unsafe.Pointer(cMessage))
	defer C.free(unsafe.Pointer(cCaption))
	defer C.free(unsafe.Pointer(cDefaultText))
	defer C.free(unsafe.Pointer(cBuffer))
	return int(C.wxGetPasswordFromUser(cMessage, cCaption, cDefaultText, parent, cBuffer))
}

